import {estimate,select,summarized,unitFor,csv,stations} from './model.js';
const $=id=>document.getElementById(id), nf=new Intl.NumberFormat('it-IT',{maximumSignificantDigits:5}),fmt=v=>v===null||v===undefined?'—':nf.format(v),date=s=>new Date(s+'T12:00:00').toLocaleDateString('it-IT',{day:'numeric',month:'short',year:'numeric'});
const colors={S1:'#1A3340',S2:'#9AB82A'},names={S1:'S1 – Fosso Galeria 1',S2:'S2 – Fosso Galeria 2'},months=['Gen','Feb','Mar','Apr','Mag','Giu','Lug','Ago','Set','Ott','Nov','Dic'];
let records=[],params=[],current=[],chart,page=0,ready=false;
const state={param:'% OSSIGENO DISCIOLTO',year:'all',method:'half',stations:['S1','S2'],view:'trend'};
const views={trend:['Andamento temporale per stazione','Serie storica dei valori rilevati in ogni punto di campionamento'],bar:['Confronto tra stazioni','Media, massimo e minimo delle osservazioni nel periodo selezionato'],seasonal:['Andamento stagionale','Medie mensili delle osservazioni disponibili nel periodo selezionato'],stats:['Statistiche per stazione','Riepilogo della selezione e confronto delle medie annuali']};
const methodNames={half:'LOQ/2',zero:'zero',limit:'LOQ',exclude:'solo valori quantificati'};
function populate(query=''){const matches=params.filter(p=>p.toLocaleLowerCase('it').includes(query.toLocaleLowerCase('it')));$('substanceSelect').replaceChildren(...matches.map(p=>new Option(p,p,false,p===state.param)));if(matches.includes(state.param))$('substanceSelect').value=state.param;else $('substanceSelect').selectedIndex=-1;$('searchStatus').textContent=query?`${matches.length} parametri trovati. Seleziona un risultato.`:'';}
function update(){if(!ready)return;current=select(records,state);page=0;const s=summarized(current,state.method),unit=unitFor(state.param,records);$('heroTitle').textContent=state.param;$('unitBadge').textContent=`Unità di misura: ${unit}`;$('mCount').textContent=fmt(s.count);$('mMean').textContent=fmt(s.mean);$('mMeanUnit').textContent=unit+(s.below&&state.method!=='exclude'?' · con stime':'');$('mMax').textContent=fmt(s.max);const peak=current.find(r=>estimate(r,state.method)===s.max&&s.max!==null);$('mMaxDate').textContent=peak?`${date(peak.date)} · ${peak.station}${peak.sign==='<'?' · stimato':''}`:'—';$('mBelow').textContent=fmt(s.below);$('mBelowPct').textContent=s.count?`${fmt(100*s.below/s.count)}% delle ${fmt(s.count)} misurazioni`:'Nessuna misurazione';
document.querySelectorAll('[data-station]').forEach(b=>{const active=state.stations.includes(b.dataset.station);b.classList.toggle('on',active);b.setAttribute('aria-pressed',String(active));b.disabled=active&&state.stations.length===1;});$('chartTitle').textContent=views[state.view][0];$('chartDesc').textContent=views[state.view][1];$('panel').setAttribute('aria-labelledby','tab-'+state.view);document.querySelectorAll('[data-view]').forEach(b=>{const active=state.view===b.dataset.view;b.classList.toggle('active',active);b.setAttribute('aria-selected',String(active));b.tabIndex=active?0:-1;});
const missing=state.stations.filter(s=>!current.some(r=>r.station===s));$('guide').textContent=(state.view==='trend'?'Come leggere: passa sui punti per data e risultato originale. I triangoli indicano valori sotto quantificazione. ':state.view==='seasonal'?'Come leggere: ogni punto è una media mensile; il numero di osservazioni può variare tra mesi e stazioni. ':'Come leggere: le statistiche usano le osservazioni disponibili, che possono differire tra stazioni. ')+(missing.length?`${missing.join(', ')}: nessuna misurazione disponibile. `:'')+(s.below?`Valori < LOQ: ${methodNames[state.method]}.`:'');
$('coverage').textContent=s.count?`${fmt(s.used)} valori nel grafico · ${date(current[0].date)} – ${date(current.at(-1).date)}`:'Nessun dato nel periodo';$('methodNote').textContent=`Medie aritmetiche · Valori sotto quantificazione: ${methodNames[state.method]}. ${s.below?`${fmt(s.below)} risultati indicati con «<», ${state.method==='exclude'?'esclusi dai calcoli':'elaborati come stime'}. `:''}I valori originali sono consultabili nella tabella e nel CSV.`;
$('download').disabled=!current.length;draw(unit);renderRows();const q=new URLSearchParams({param:state.param,anno:state.year,metodo:state.method,stazioni:state.stations.join(','),vista:state.view});history.replaceState(null,'','?'+q.toString());}
function draw(unit){chart?.destroy();chart=null;const usable=current.filter(r=>estimate(r,state.method)!==null);$('empty').hidden=usable.length>0;$('chart').hidden=!usable.length;$('summary').hidden=state.view!=='stats';if(state.view==='stats')renderSummary();if(!usable.length)return;if(typeof Chart==='undefined'){$('empty').textContent='Grafico non disponibile. Consulta la tabella dei dati o scarica il CSV.';$('empty').hidden=false;return;}
const validLog=usable.every(r=>estimate(r,state.method)>0);$('log').disabled=!validLog;if(!validLog)$('log').checked=false;$('log').parentElement.title=validLog?'':'La scala logaritmica richiede valori strettamente positivi.';
let labels,datasets,type='line';const visible=state.stations.filter(s=>current.some(r=>r.station===s));
if(state.view==='trend'){datasets=visible.map(s=>({label:names[s],data:current.filter(r=>r.station===s).map(r=>({x:Date.parse(r.date+'T12:00:00Z'),y:estimate(r,state.method),record:r})),borderColor:colors[s],backgroundColor:colors[s]+'12',pointBackgroundColor:colors[s],pointStyle:ctx=>ctx.raw?.record?.sign==='<'?'triangle':'circle',pointRadius:3,pointHoverRadius:6,borderWidth:2,fill:false,tension:0,spanGaps:false}));}
else if(state.view==='bar'){type='bar';labels=visible.map(s=>names[s]);datasets=[['Media','mean','#1A3340'],['Massimo','max','#B8D432'],['Minimo','min','#7898A5']].map(([label,key,color])=>({label,data:visible.map(s=>summarized(current.filter(r=>r.station===s),state.method)[key]),backgroundColor:color,borderRadius:3}));}
else{type=state.view==='stats'?'bar':'line';labels=state.view==='stats'?[...new Set(current.map(r=>r.date.slice(0,4)))].sort():months;datasets=visible.map(s=>({label:names[s],data:labels.map((label,index)=>{const subset=current.filter(r=>r.station===s&&(state.view==='stats'?r.date.startsWith(label):Number(r.date.slice(5,7))===index+1));const stats=summarized(subset,state.method);return {x:label,y:stats.mean,n:stats.used};}),borderColor:colors[s],backgroundColor:state.view==='stats'?colors[s]:colors[s]+'12',pointBackgroundColor:colors[s],pointRadius:4,borderWidth:2,fill:false,tension:0,spanGaps:false}));}
const options={responsive:true,maintainAspectRatio:false,animation:false,interaction:{mode:'nearest',intersect:false},plugins:{legend:{position:'bottom',labels:{color:'#4A5568',font:{family:'Barlow',size:14},boxWidth:12,padding:20}},tooltip:{backgroundColor:'#1A3340',titleColor:'#F0EDE6',bodyColor:'#F0EDE6',padding:12,callbacks:{title:items=>state.view==='trend'?date(items[0].raw.record.date):items[0].label,label:item=>{const raw=item.raw;if(raw?.record){const r=raw.record;return [`${r.station}: ${r.sign==='<'?'< ':''}${fmt(r.value)} ${r.unit}`,r.sign==='<'?`Stima ${methodNames[state.method]}: ${fmt(raw.y)} ${unit}`:'Risultato quantificato'];}return `${item.dataset.label}: ${fmt(item.parsed.y)} ${unit}${raw?.n?' · n = '+raw.n:''}`;}}}},scales:{x:{grid:{color:'#1A33400B'},ticks:{font:{family:'Barlow',size:13},color:'#4A5568',maxTicksLimit:10}},y:{type:$('log').checked?'logarithmic':'linear',beginAtZero:!$('log').checked,title:{display:true,text:unit,color:'#4A5568'},ticks:{callback:v=>fmt(v),font:{size:13}},grid:{color:'#1A334014'}}}};
if(state.view==='trend'){options.scales.x.type='linear';options.scales.x.ticks.callback=v=>new Date(v).toLocaleDateString('it-IT',{month:'short',year:'2-digit'});}
chart=new Chart($('chart'),{type,data:{labels,datasets},options});}
function td(value){const cell=document.createElement('td');cell.textContent=value;return cell;}
function renderSummary(){$('summary').replaceChildren();const table=document.createElement('table');table.className='stats-table';table.innerHTML='<thead><tr><th>Stazione</th><th>n. totali</th><th>n. usati</th><th>Media</th><th>Mediana</th><th>Max</th><th>Min</th><th>&lt; LOQ</th></tr></thead>';const body=document.createElement('tbody');state.stations.forEach(st=>{const s=summarized(current.filter(r=>r.station===st),state.method),tr=document.createElement('tr');[st,s.count,s.used,s.mean,s.median,s.max,s.min,s.below].forEach((v,i)=>tr.append(td(i===0?v:fmt(v))));body.append(tr);});table.append(body);$('summary').append(table);}
function renderRows(){const rows=[...current].reverse(),pages=Math.max(1,Math.ceil(rows.length/30));page=Math.min(page,pages-1);$('rawBody').replaceChildren(...rows.slice(page*30,page*30+30).map(r=>{const tr=document.createElement('tr');[date(r.date),r.station,(r.sign==='<'?'< ':'')+fmt(r.value),fmt(estimate(r,state.method)),r.unit,`${r.source} · ${r.row}`].forEach(v=>tr.append(td(v)));return tr;}));$('rawCount').textContent=`· ${fmt(rows.length)} righe`;$('pageInfo').textContent=`Pagina ${page+1} di ${pages}`;$('prev').disabled=page===0;$('next').disabled=page===pages-1;}
$('search').addEventListener('input',e=>populate(e.target.value));$('substanceSelect').addEventListener('change',e=>{state.param=e.target.value;update();});$('year').addEventListener('change',e=>{state.year=e.target.value;update();});$('method').addEventListener('change',e=>{state.method=e.target.value;update();});$('log').addEventListener('change',()=>draw(unitFor(state.param,records)));
document.querySelectorAll('[data-station]').forEach(b=>b.addEventListener('click',()=>{const s=b.dataset.station;state.stations=state.stations.includes(s)?state.stations.filter(x=>x!==s):stations.filter(x=>state.stations.includes(x)||x===s);update();}));const tabs=[...document.querySelectorAll('[data-view]')];tabs.forEach((b,i)=>{b.addEventListener('click',()=>{state.view=b.dataset.view;update();});b.addEventListener('keydown',e=>{if(!['ArrowRight','ArrowLeft','Home','End'].includes(e.key))return;e.preventDefault();const n=e.key==='Home'?0:e.key==='End'?3:(i+(e.key==='ArrowRight'?1:3))%4;tabs[n].focus();tabs[n].click();});});
$('reset').addEventListener('click',()=>{Object.assign(state,{param:'% OSSIGENO DISCIOLTO',year:'all',method:'half',stations:['S1','S2'],view:'trend'});$('search').value='';$('year').value='all';$('method').value='half';$('log').checked=false;populate();update();});$('prev').onclick=()=>{page--;renderRows();};$('next').onclick=()=>{page++;renderRows();};$('download').onclick=()=>{const a=document.createElement('a'),url=URL.createObjectURL(new Blob([csv(current,state.method)],{type:'text/csv;charset=utf-8'}));a.href=url;a.download=`galeria-${state.param.replace(/[^a-z0-9]+/gi,'-')}-${state.year}.csv`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};
const dialog=$('infoDialog');let previousFocus;function openInfo(){previousFocus=document.activeElement;dialog.showModal();document.body.style.overflow='hidden';}function closeInfo(){dialog.close();}['info','sources'].forEach(id=>$(id).onclick=openInfo);$('closeInfo').onclick=closeInfo;dialog.addEventListener('close',()=>{document.body.style.overflow='';previousFocus?.focus();});dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeInfo();}});
async function init(){try{const response=await fetch('data.json');if(!response.ok)throw Error('data');const data=await response.json();records=data.records;params=[...new Set(records.map(r=>r.param))].sort((a,b)=>a.localeCompare(b,'it'));const q=new URLSearchParams(location.search);if(params.includes(q.get('param')))state.param=q.get('param');if(['all','2020','2021','2022','2023','2024','2025'].includes(q.get('anno')))state.year=q.get('anno');if(Object.hasOwn(methodNames,q.get('metodo')))state.method=q.get('metodo');if(Object.hasOwn(views,q.get('vista')))state.view=q.get('vista');const st=q.get('stazioni')?.split(',').filter(s=>stations.includes(s));if(st?.length)state.stations=[...new Set(st)];$('year').value=state.year;$('method').value=state.method;populate();ready=true;$('status').textContent='';update();registerTools();}catch(e){$('status').textContent='Impossibile caricare i dati. Ricarica la pagina per riprovare.';console.error(e);}}
function registerTools(){if(!document.modelContext?.registerTool)return;try{Promise.resolve(document.modelContext.registerTool({name:'filter_galeria',description:'Imposta parametro e anno nei filtri visibili della dashboard del Fosso Galeria.',inputSchema:{type:'object',properties:{parametro:{type:'string'},anno:{type:'string',enum:['all','2020','2021','2022','2023','2024','2025']}},required:['parametro','anno'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:true},execute(input){if(!input||typeof input!=='object'||!params.includes(input.parametro)||!['all','2020','2021','2022','2023','2024','2025'].includes(input.anno))throw Error('Parametro o anno non valido');state.param=input.parametro;state.year=input.anno;$('search').value='';populate();$('year').value=state.year;update();return {parametro:state.param,anno:state.year,...summarized(current,state.method)};}})).catch(()=>{});}catch{}}
init();
